declare_lint ! { # [doc = " The `drop_bounds` lint checks for generics with `std::ops::Drop` as"] # [doc = " bounds."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " fn foo<T: Drop>() {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " A generic trait bound of the form `T: Drop` is most likely misleading"] # [doc = " and not what the programmer intended (they probably should have used"] # [doc = " `std::mem::needs_drop` instead)."] # [doc = ""] # [doc = " `Drop` bounds do not actually indicate whether a type can be trivially"] # [doc = " dropped or not, because a composite type containing `Drop` types does"] # [doc = " not necessarily implement `Drop` itself. Naïvely, one might be tempted"] # [doc = " to write an implementation that assumes that a type can be trivially"] # [doc = " dropped while also supplying a specialization for `T: Drop` that"] # [doc = " actually calls the destructor. However, this breaks down e.g. when `T`"] # [doc = " is `String`, which does not implement `Drop` itself but contains a"] # [doc = " `Vec`, which does implement `Drop`, so assuming `T` can be trivially"] # [doc = " dropped would lead to a memory leak here."] # [doc = ""] # [doc = " Furthermore, the `Drop` trait only contains one method, `Drop::drop`,"] # [doc = " which may not be called explicitly in user code (`E0040`), so there is"] # [doc = " really no use case for using `Drop` in trait bounds, save perhaps for"] # [doc = " some obscure corner cases, which can use `#[allow(drop_bounds)]`."] pub DROP_BOUNDS , Warn , "bounds of the form `T: Drop` are most likely incorrect" }